-- ============================================================
-- Climactix Global — Dynamic Materiality Engine Migration 003
-- Aspect weights, materiality scores, and framework mappings
-- live here so methodology can evolve without code changes.
-- Idempotent: safe to run on every backend startup.
-- ============================================================

-- ── Categories & Sub-Aspects (server-side mirror of aspect-impact-data.js) ──
CREATE TABLE IF NOT EXISTS materiality_categories (
  id          TEXT PRIMARY KEY,
  label       TEXT NOT NULL,
  description TEXT NOT NULL,
  sort_order  SMALLINT NOT NULL
);

CREATE TABLE IF NOT EXISTS materiality_sub_aspects (
  id          TEXT PRIMARY KEY,
  category_id TEXT NOT NULL REFERENCES materiality_categories(id),
  label       TEXT NOT NULL,
  description TEXT NOT NULL,
  sort_order  SMALLINT NOT NULL
);



-- ── Industry applicability: default-applicable, this table lists exclusions only ──
CREATE TABLE IF NOT EXISTS materiality_industry_exclusions (
  industry_key TEXT NOT NULL CHECK (industry_key IN ('banking','manufacturing','logistics','energy','real_estate','data_centers','it_services','ports','agriculture','healthcare','retail')),
  sub_aspect_id TEXT NOT NULL REFERENCES materiality_sub_aspects(id),
  reason        TEXT NOT NULL,
  PRIMARY KEY (industry_key, sub_aspect_id)
);


-- ── The 12 materiality parameters + global weights (sum to 100, revisable) ──
CREATE TABLE IF NOT EXISTS materiality_parameters (
  id           TEXT PRIMARY KEY,
  label        TEXT NOT NULL,
  global_weight NUMERIC(5,2) NOT NULL CHECK (global_weight >= 0),
  sort_order   SMALLINT NOT NULL
);


-- ── Category-level 12-parameter materiality scores (Climate & Water only — fully authored) ──
CREATE TABLE IF NOT EXISTS materiality_category_parameter_scores (
  industry_key TEXT NOT NULL CHECK (industry_key IN ('banking','manufacturing','logistics','energy','real_estate','data_centers','it_services','ports','agriculture','healthcare','retail')),
  category_id   TEXT NOT NULL CHECK (category_id IN ('climate','water')),
  parameter_id  TEXT NOT NULL REFERENCES materiality_parameters(id),
  score         SMALLINT NOT NULL CHECK (score BETWEEN 1 AND 5),
  PRIMARY KEY (industry_key, category_id, parameter_id)
);


-- ── Baseline significance tiers for the other 7 categories (not yet parameter-decomposed) ──
CREATE TABLE IF NOT EXISTS materiality_baseline_tiers (
  industry_key TEXT NOT NULL CHECK (industry_key IN ('banking','manufacturing','logistics','energy','real_estate','data_centers','it_services','ports','agriculture','healthcare','retail')),
  category_id   TEXT NOT NULL CHECK (category_id NOT IN ('climate','water')),
  tier          TEXT NOT NULL CHECK (tier IN ('insignificant','low','moderate','high','critical')),
  rationale     TEXT NOT NULL,
  PRIMARY KEY (industry_key, category_id)
);
-- NOTE: these are direct classifications, not decomposed across the 12 parameters.
-- Candidates for future upgrade to materiality_category_parameter_scores once
-- those categories receive full content authoring (see judgment calls in the plan).


-- ── Framework crosswalk (server-side copy of aspect-impact-data.js FRAMEWORK_CROSSWALK) ──
CREATE TABLE IF NOT EXISTS materiality_framework_crosswalk (
  id                          TEXT PRIMARY KEY,
  category_id                 TEXT NOT NULL REFERENCES materiality_categories(id),
  framework                   TEXT NOT NULL,
  clause                      TEXT NOT NULL,
  requirement                 TEXT NOT NULL,
  evidence_required           TEXT NOT NULL,
  min_evidence_for_compliance TEXT NOT NULL CHECK (min_evidence_for_compliance IN ('not_supported','estimated','document_supported','audited','verified')),
  sort_order                  SMALLINT NOT NULL
);


-- ── Adaptive question tiers (Climate & Water only — fully authored base + expanded) ──
CREATE TABLE IF NOT EXISTS materiality_question_tiers (
  question_id  TEXT PRIMARY KEY,
  sub_aspect_id TEXT NOT NULL REFERENCES materiality_sub_aspects(id),
  tier         TEXT NOT NULL CHECK (tier IN ('base','expanded')),
  label        TEXT NOT NULL,
  sublabel     TEXT,
  type         TEXT NOT NULL CHECK (type IN ('yesno','dropdown','number','text')),
  unit         TEXT,
  min_words    SMALLINT,
  weight       NUMERIC(5,2) NOT NULL DEFAULT 1.0,
  sort_order   SMALLINT NOT NULL
);

CREATE TABLE IF NOT EXISTS materiality_question_options (
  id          TEXT PRIMARY KEY DEFAULT encode(gen_random_bytes(8), 'hex'),
  question_id TEXT NOT NULL REFERENCES materiality_question_tiers(question_id) ON DELETE CASCADE,
  label       TEXT NOT NULL,
  score       SMALLINT NOT NULL CHECK (score BETWEEN 0 AND 100),
  sort_order  SMALLINT NOT NULL
);

