INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('banking', 'air', 'insignificant', 'No direct combustion or process air emissions from financial services operations.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('manufacturing', 'air', 'critical', 'Combustion and process emissions are material across heavy industry operations.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('logistics', 'air', 'high', 'Fleet and terminal operations generate material vehicle and equipment emissions.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('energy', 'air', 'critical', 'Combustion, flaring and power generation are core sources of air emissions.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('real_estate', 'air', 'low', 'Limited to backup generators, HVAC systems and construction-phase dust.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('data_centers', 'air', 'low', 'Emissions limited to backup diesel generators during outages.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('it_services', 'air', 'insignificant', 'No industrial or combustion-based emission sources in software/services operations.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('ports', 'air', 'high', 'Vessel, equipment and cargo-handling activity generate material air emissions.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('agriculture', 'air', 'moderate', 'Machinery use, livestock emissions and occasional field burning contribute meaningfully.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('healthcare', 'air', 'moderate', 'Medical incineration and boiler operations create limited but real emissions.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('retail', 'air', 'insignificant', 'Store operations generate no material direct air emissions.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('banking', 'waste', 'low', 'Limited to routine office and IT-equipment waste.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('manufacturing', 'waste', 'critical', 'Process byproducts and hazardous waste streams are material to operations.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('logistics', 'waste', 'moderate', 'Packaging materials and vehicle maintenance generate meaningful waste volumes.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('energy', 'waste', 'high', 'Drilling waste, ash and decommissioning waste are significant across the sector.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('real_estate', 'waste', 'moderate', 'Construction and demolition waste is material during development cycles.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('data_centers', 'waste', 'moderate', 'E-waste and battery disposal from hardware refresh cycles.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('it_services', 'waste', 'low', 'Limited to periodic hardware e-waste from equipment refresh.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('ports', 'waste', 'moderate', 'Cargo residues and vessel waste handling generate material volumes.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('agriculture', 'waste', 'high', 'Agrochemical containers and organic/animal waste streams are significant.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('healthcare', 'waste', 'critical', 'Biomedical and hazardous waste streams require intensive management.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('retail', 'waste', 'moderate', 'Packaging waste and unsold inventory disposal are material.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('banking', 'biodiversity', 'low', 'Impact is indirect, arising only through financed activities.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('manufacturing', 'biodiversity', 'moderate', 'Facility footprints can disturb local habitats depending on siting.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('logistics', 'biodiversity', 'moderate', 'Infrastructure corridors and depot siting affect local land use.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('energy', 'biodiversity', 'critical', 'Extraction sites and pipeline/transmission corridors cause material land disturbance.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('real_estate', 'biodiversity', 'high', 'Land development directly converts and fragments natural habitats.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('data_centers', 'biodiversity', 'low', 'Impact limited to the facility footprint itself.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('it_services', 'biodiversity', 'insignificant', 'No material land-use or habitat footprint.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('ports', 'biodiversity', 'high', 'Dredging and coastal works materially disturb marine and coastal habitats.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('agriculture', 'biodiversity', 'critical', 'Land conversion, monoculture and pesticide use materially affect biodiversity.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('healthcare', 'biodiversity', 'insignificant', 'No material land-use or habitat footprint beyond facility siting.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('retail', 'biodiversity', 'low', 'Impact limited to store and distribution-center footprints.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('banking', 'resource_efficiency', 'low', 'Limited to office consumables and IT hardware procurement.') ON CONFLICT (industry_key, category_id) DO NOTHING;
