INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('logistics', 'resource_efficiency', 'moderate', 'Packaging materials and fuel/vehicle resource consumption are material.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('energy', 'resource_efficiency', 'high', 'Extraction and generation assets are resource-intensive to build and maintain.') ON CONFLICT (industry_key, category_id) DO NOTHING;
