INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('it_services', 'resource_efficiency', 'low', 'Limited to periodic hardware procurement.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('ports', 'resource_efficiency', 'moderate', 'Infrastructure and equipment materials are periodically material.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('agriculture', 'resource_efficiency', 'high', 'Water, soil and agrochemical input intensity are significant.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('healthcare', 'resource_efficiency', 'moderate', 'Medical supply and consumable consumption is material.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('retail', 'resource_efficiency', 'high', 'Packaging and merchandise material throughput is a core impact area.') ON CONFLICT (industry_key, category_id) DO NOTHING;
INSERT INTO materiality_baseline_tiers (industry_key, category_id, tier, rationale) VALUES ('banking', 'pollution', 'insignificant', 'No material direct pollution sources in financial services operations.') ON CONFLICT (industry_key, category_id) DO NOTHING;
